import { PaintVoxelData } from "../Types/PaintVoxelData";
import { VoxelSchemas } from "../State/VoxelSchemas";
import { VoxelLUT } from "../../Voxels/Data/VoxelLUT";
export class VoxelNamedState {
    voxelId;
    data;
    tags = new Map();
    compiled = {
        mod: 0,
        modAny: false,
        state: 0,
        stateAny: false,
    };
    constructor(voxelId, data) {
        this.voxelId = voxelId;
        this.data = data;
        for (const key in data.properties) {
            this.tags.set(key, data.properties[key]);
        }
        const stateSchema = VoxelSchemas.getStateSchema(this.voxelId);
        if (this.data.state == "*") {
            this.compiled.stateAny = true;
        }
        else if (this.data.state && stateSchema) {
            this.compiled.state = stateSchema.readString(this.data.state);
        }
        const modSchema = VoxelSchemas.mod.get(voxelId);
        if (this.data.mod == "*") {
            this.compiled.modAny = true;
        }
        else if (this.data.mod && modSchema) {
            this.compiled.mod = modSchema.readString(this.data.mod);
        }
    }
    getPaintData() {
        return PaintVoxelData.Create({
            id: this.voxelId,
            level: 0,
            levelState: 0,
            state: this.compiled.state,
            mod: this.compiled.mod,
        });
    }
}
export class VoxelNamedStateContainer {
    voxelId;
    states = new Map();
    stateArray = [];
    constructor(voxelId, data) {
        this.voxelId = voxelId;
        for (const state of data) {
            this.states.set(state.data.id, state);
            this.stateArray.push(state);
        }
    }
}
class TagIndex {
    tagId;
    states = new Map();
    //maps named state to the value of the tag
    valueMap = new Map();
    values = new Set();
    constructor(tagId) {
        this.tagId = tagId;
    }
}
export class VoxelIndex {
    static instance;
    dataMap = new Map();
    states = new Map();
    stateArray = [];
    tagIndexes = new Map();
    constructor(data) {
        if (VoxelIndex.instance)
            return VoxelIndex.instance;
        if (!VoxelIndex.instance)
            VoxelIndex.instance = this;
        for (const voxelData of data) {
            this.dataMap.set(voxelData.id, voxelData);
            const namedStates = voxelData.properties["dve_named_states"];
            if (!namedStates)
                continue;
            const states = new VoxelNamedStateContainer(voxelData.id, namedStates.map((_) => new VoxelNamedState(voxelData.id, _)));
            this.stateArray.push(states);
            this.states.set(voxelData.id, states);
            for (const [id, state] of states.states) {
                for (const tagId in state.data.properties) {
                    const tagData = state.data.properties[tagId];
                    let tag = this.tagIndexes.get(tagId);
                    if (!tag) {
                        tag = new TagIndex(tagId);
                        this.tagIndexes.set(tagId, tag);
                    }
                    tag.states.set(state.data.id, state);
                    tag.states.set(state.data.id, tagData);
                    tag.values.add(tagData);
                }
            }
        }
    }
    findState(conatiner, mod, state) {
        for (const modelState of conatiner?.stateArray) {
            if ((mod == modelState.compiled.mod || modelState.compiled.modAny) &&
                (state == modelState.compiled.state || modelState.compiled.stateAny))
                return modelState;
        }
        return false;
    }
    getStateFromPaintData(data) {
        const conatiner = this.states.get(data.id);
        if (!conatiner)
            return false;
        const { mod, state } = data;
        return this.findState(conatiner, mod, state);
    }
    getStateFromRawData(data) {
        const [id, light, secondary] = data;
        const trueId = VoxelLUT.voxelIdToTrueId[id];
        const state = VoxelLUT.voxelIdToState[id];
        const mod = VoxelLUT.voxelIdToMod[id];
        const conatiner = this.states.get(VoxelLUT.voxelIds.getStringId(trueId));
        if (!conatiner)
            return false;
        return this.findState(conatiner, mod, state);
    }
}
